cases.good:
export async function saveSettings(settings: Partial<Settings>): Promise<void> {
  // read-modify-write: load current, merge partial, write back
  const current = await loadSettings();
  const toStore = { ...current, ...settings, schemaVersion: CURRENT_SCHEMA_VERSION };
  await setStorage({ [STORAGE_KEYS.SETTINGS]: toStore });
}
// Callers passing full settings ({...settings, [field]: value}) are unaffected — full merged with full = full

